data.default.conf:
server { listen 80 default_server; server_name _; location / { return 404; } }
server { listen 80; server_name dev.cormibo.com; location / {
resolver kube-dns.kube-system.svc.cluster.local valid=10s;
set $upstream "cormibo-development.app.svc.cluster.local:80";
add_header X-Robots-Tag "noindex, nofollow" always;
add_header Cache-Control "no-store" always;
if ($request_method !~ ^(GET|HEAD|OPTIONS)$) { return 405; }
proxy_set_header Host $host;
proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_pass http://$upstream;
} }
server { listen 80; server_name dev.ddwellers.com;
add_header X-Robots-Tag "noindex, nofollow, noimageindex" always;
add_header Cache-Control "no-store" always;
location = /cormibo { return 308 /cormibo/; }
location /cormibo/ {
resolver kube-dns.kube-system.svc.cluster.local valid=10s;
set $upstream "cormibo-development.app.svc.cluster.local:80";
add_header X-Robots-Tag "noindex, nofollow" always;
add_header Cache-Control "no-store" always;
if ($request_method !~ ^(GET|HEAD|OPTIONS)$) { return 405; }
rewrite ^/cormibo/(.*)$ /$1 break;
proxy_set_header Host $host;
proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_pass http://$upstream;
}
location / {
resolver kube-dns.kube-system.svc.cluster.local valid=10s;
set $upstream "app.app.svc.cluster.local:80";
proxy_set_header Host $host;
proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
proxy_pass http://$upstream;
} }
